# TTL cache with negative caching (simulated clock)
class DnsCache:
    def __init__(self):
        self.items = {}  # name -> (value, expires_at); value None = "does not exist"
    def put(self, name, value, ttl, now):
        self.items[name] = (value, now + ttl)
    def get(self, name, now):
        if name in self.items:
            value, exp = self.items[name]
            if now < exp:                 # still fresh
                return "HIT", value
            del self.items[name]          # expired: drop it
        return "MISS", None

c = DnsCache()
c.put("api.example.com", "10.0.0.5", 300, now=0)     # normal record, TTL 300 s
c.put("typo.example.com", None, 60, now=0)           # negative answer cached 60 s
for t in (0, 59, 61, 299, 301):
    print("t=%3d api:" % t, c.get("api.example.com", t),
          "| typo:", c.get("typo.example.com", t))

# Health check hysteresis: fall=3 failures to mark down, rise=2 successes to mark up
FALL, RISE = 3, 2
interval = 5  # seconds between probes

def run(results):
    up, fails, oks = True, 0, 0
    for i, ok in enumerate(results):
        if ok:
            oks += 1; fails = 0
            if not up and oks >= RISE:
                up = True
        else:
            fails += 1; oks = 0
            if up and fails >= FALL:
                up = False
        print("probe %2d t=%3ds %-4s -> %s" % (i, i * interval, "ok" if ok else "FAIL", "UP" if up else "DOWN"))

# one blip (ignored), then a real outage, then recovery
probes = [True, False, True, True, False, False, False, True, False, True, True]
print("probes:", probes)
run(probes)
print("detection time ~ interval * fall =", interval * FALL, "s")

# Consistent hashing ring with virtual nodes: how many keys move when a server is added?
import bisect, hashlib

def h(s):
    return int(hashlib.md5(s.encode()).hexdigest(), 16)

def build(servers, vnodes=100):
    ring = sorted((h(s + "#" + str(i)), s) for s in servers for i in range(vnodes))
    return ring, [p for p, _ in ring]

def lookup(ring, points, key):
    i = bisect.bisect(points, h(key)) % len(ring)   # next point clockwise
    return ring[i][1]

keys = ["user%d" % i for i in range(1000)]
ring3, pts3 = build(["A", "B", "C"])
ring4, pts4 = build(["A", "B", "C", "D"])
before = {k: lookup(ring3, pts3, k) for k in keys}
after = {k: lookup(ring4, pts4, k) for k in keys}
moved = sum(1 for k in keys if before[k] != after[k])
print("keys:", len(keys), "servers 3 -> 4")
print("moved with consistent hashing:", moved, "(ideal ~250)")
mod = sum(1 for k in keys if h(k) % 3 != h(k) % 4)
print("moved with hash % N:", mod)
